<template>
  <div class="import-fee-page">
    <AdminPageHeader title="กรอกค่านำเข้าสินค้าพรีออเดอร์" description="กรอกตามสินค้าหลัก ระบบรวมรสชาติและกระจายยอดตามแพ็กที่สั่งจริง"></AdminPageHeader>
    <div class="card selector-card">
      <label class="field-label">เลือกรอบพรีออเดอร์</label>
      <div class="select-row">
        <div class="select-wrap">
          <select v-model="selectedRoundId" class="round-select" :disabled="loading">
            <option value="" disabled>— เลือกรอบพรีออเดอร์ —</option>
            <option v-for="r in rounds" :key="r.round_key" :value="r.round_key">{{ r.round_name }}</option>
          </select>
          <svg class="select-chevron" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><polyline points="6 9 12 15 18 9" /></svg>
        </div>
        <span v-if="selectedRound" class="round-badge" :class="statusBadgeClass(selectedRound.round_status)">{{ statusLabel(selectedRound.round_status) }}</span>
        <span v-if="loading" class="spinner" aria-label="กำลังโหลด"></span>
      </div>
    </div>

    <div v-if="selectedRound && primaryProducts.length > 0" class="card table-card fee-table">
      <div class="table-header">
        <div><span class="table-title">รายการสินค้าในรอบ <b>{{ selectedRound.round_name }}</b></span><p class="table-hint">กรอกค่านำเข้าที่สินค้าหลักได้เลย หากมีหลายขนาดให้กรอกแยกใน Dropdown</p></div>
        <span class="table-count">{{ primaryProducts.length }} สินค้าหลัก</span>
      </div>
      <div class="product-list">
        <article v-for="product in primaryProducts" :key="product.key" class="product-card" :class="{ 'product-card--expanded': isExpanded(product.key) }">
          <div class="product-main-row">
            <div class="product-cell product-cell--main">
              <button v-if="product.image_url" type="button" class="thumb-btn" @click="openImagePreview(product.image_url, product.product_name)" :aria-label="`ดูรูป ${product.product_name}`"><img :src="product.image_url" :alt="product.product_name" class="product-cell-thumb" loading="lazy" /></button>
              <div v-else class="product-cell-thumb product-cell-thumb--placeholder">🐾</div>
              <div class="product-copy"><div class="product-name">{{ product.product_name }}</div><div class="product-code">รหัสสินค้า #{{ product.prod_id }} · {{ product.variantCount }} รายการย่อย · {{ product.customerCount }} ลูกค้า</div></div>
            </div>
            <div class="main-metric"><span>แพ็กที่สั่งรวม</span><strong>{{ product.totalQty }} แพ็ก</strong></div>
            <div class="main-metric main-metric--fee"><span>ค่านำเข้ารวม</span><div v-if="!product.hasMultiplePackSizes && !isGroupInputLocked(product.packGroups[0])" class="fee-input-wrap"><span class="fee-prefix">฿</span><input type="text" inputmode="decimal" class="fee-input" :value="feeInputs[product.packGroups[0].key]" @input="onFeeInput(product.packGroups[0].key, $event)" @blur="onFeeInputBlur(product.packGroups[0].key)" :disabled="saving || (hasSavedImportFee && !isEditMode)" maxlength="13" placeholder="0.00" /></div><span v-else class="main-fee-total">{{ formatMoney(product.totalFee) }}</span></div>
            <div class="main-metric"><span>{{ product.hasMultiplePackSizes ? 'ค่านำเข้าเฉลี่ย' : 'เฉลี่ย / แพ็ก' }}</span><strong>{{ product.hasMultiplePackSizes ? 'แยกตามขนาด' : formatMoney(product.averageFee) }}</strong></div>
            <button type="button" class="dropdown-btn" @click="toggleExpanded(product.key)" :aria-expanded="isExpanded(product.key)"><span>{{ isExpanded(product.key) ? 'ย่อ' : 'รายละเอียด' }}</span><span class="dropdown-chevron" :class="{ 'dropdown-chevron--open': isExpanded(product.key) }">⌄</span></button>
          </div>
          <div v-if="isExpanded(product.key)" class="detail-panel">
            <div class="detail-panel-head"><div><strong>รายละเอียดตัวเลือกสินค้า</strong><span>รวมรสชาติภายในขนาดเดียวกัน</span></div><span class="detail-total">{{ product.totalQty }} แพ็ก · {{ product.customerCount }} ลูกค้า</span></div>
            <div v-for="packGroup in product.packGroups" :key="packGroup.key" class="pack-group">
              <div class="pack-group-head"><div><span class="pack-chip">{{ packLabel(packGroup.pack_size) }}</span><span class="pack-subtitle">{{ packGroup.totalQty }} แพ็ก · {{ packGroup.customerCount }} ลูกค้า · {{ packGroup.items.length }} รสชาติ</span></div><div v-if="product.hasMultiplePackSizes" class="pack-fee-entry"><span class="pack-average">เฉลี่ย {{ formatMoney(packGroup.averageFee) }} / แพ็ก</span><div v-if="!isGroupInputLocked(packGroup)" class="fee-input-wrap"><span class="fee-prefix">฿</span><input type="text" inputmode="decimal" class="fee-input" :value="feeInputs[packGroup.key]" @input="onFeeInput(packGroup.key, $event)" @blur="onFeeInputBlur(packGroup.key)" :disabled="saving || (hasSavedImportFee && !isEditMode)" maxlength="13" placeholder="0.00" /></div><span v-else class="fee-locked-chip">{{ formatMoney(packGroup.totalFee) }}</span></div><div v-else class="pack-readonly-fee">ค่านำเข้ารวม {{ formatMoney(packGroup.totalFee) }} · เฉลี่ย {{ formatMoney(packGroup.averageFee) }} / แพ็ก</div></div>
              <div class="flavor-list"><div v-for="item in packGroup.items" :key="item.key" class="flavor-row"><span class="flavor-tag">{{ item.flavorDisplay || 'ไม่ระบุรสชาติ' }}</span><span>{{ item.ordered_qty }} แพ็ก <small>รับ {{ item.total_received_qty }} แพ็ก</small></span></div></div>
            </div>
          </div>
        </article>
      </div>
      <div class="note-warning"><span aria-hidden="true">ⓘ</span><span>ระบบหารค่านำเข้าตามจำนวนแพ็กที่สั่งจริง ไม่ใช่จำนวนลูกค้า · ขนาดแพ็กที่ไม่มีข้อมูลจะแสดงเป็น “ไม่ระบุขนาด” และจะไม่ถูกเดาจากชื่อสินค้า</span></div>
      <div v-if="hasUnspecifiedPackSize" class="note-warning note-warning--info"><span aria-hidden="true">⚠</span><span>ข้อมูลเดิมบางรายการยังไม่มีขนาดแพ็กในฐานข้อมูล ระบบจึงแยกไว้เป็นกลุ่ม “ไม่ระบุขนาด” เพื่อป้องกันการรวมผิดกลุ่ม</span></div>
      <div class="actions"><button v-if="hasSavedImportFee && !isEditMode" class="btn-edit" type="button" :disabled="saving || loading" @click="requestEdit">แก้ไขค่านำเข้า</button><button class="btn-save" @click="openSavePreview" :disabled="saving || loading || (hasSavedImportFee && !isEditMode)"><span v-if="saving" class="spinner spinner--sm" aria-hidden="true"></span>{{ saving ? 'กำลังบันทึก...' : 'ตรวจสอบและบันทึก' }}</button><transition name="fade"><div v-if="successMessage" class="toast toast--success">✓ {{ successMessage }}</div></transition><transition name="fade"><div v-if="errorMessage" class="toast toast--error">✕ {{ errorMessage }}</div></transition></div>
    </div>
    <div v-else-if="selectedRound && !loading" class="empty-state"><p>รอบนี้ยังไม่มีรายการที่พร้อมกรอกค่านำเข้า</p></div>
    <div v-else-if="!loading" class="empty-state"><p>เลือกรอบพรีออเดอร์เพื่อเริ่มกรอกค่านำเข้า</p></div>

    <div v-if="showPreview" class="modal-overlay" @click.self="showPreview = false"><div class="preview-modal-card"><div class="preview-modal-head"><div><h2>ตรวจสอบก่อนบันทึก</h2><p>ยอดนี้จะถูกกระจายไปยังรายละเอียดออเดอร์ตามจำนวนแพ็ก และไม่สร้างรายการค่านำเข้าซ้ำ</p></div><button type="button" class="image-modal-close" @click="showPreview = false" aria-label="ปิด">✕</button></div><div class="preview-list"><div v-for="row in previewRows" :key="row.key" class="preview-row"><div><strong>{{ row.product_name }}</strong><span>{{ packLabel(row.pack_size) }} · {{ row.totalQty }} แพ็ก</span></div><div class="preview-amount"><b>{{ formatMoney(row.fee) }}</b><small>{{ formatMoney(row.averageFee) }} / แพ็ก</small></div></div></div><div class="preview-total"><span>ค่านำเข้ารวมทั้งหมด</span><strong>{{ formatMoney(previewTotal) }}</strong></div><div class="preview-actions"><button type="button" class="btn-edit" @click="showPreview = false">กลับไปแก้ไข</button><button type="button" class="btn-save" @click="saveImportFees">ยืนยันบันทึก</button></div></div></div>
    <div v-if="previewImage" class="modal-overlay" @click.self="closeImagePreview"><div class="image-modal-card"><button type="button" class="image-modal-close" @click="closeImagePreview" aria-label="ปิด">✕</button><img :src="previewImage.url" :alt="previewImage.title" class="image-modal-img" /><p class="image-modal-caption">{{ previewImage.title }}</p></div></div>
  </div>
</template>

<script setup>
import AdminPageHeader from '../../components/AdminPageHeader.vue'
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useAuth } from '../../composables/useAuth'
import translateError from '../../utils/translateError'

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || '/api'
const { getUser } = useAuth()
const currentUser = computed(() => getUser())
const rounds = ref([]), selectedRoundId = ref(''), feeInputs = ref({}), expandedProductKeys = ref(new Set())
const loading = ref(false), saving = ref(false), isEditMode = ref(false), savedRoundKeys = ref(loadSavedRoundKeys())
const successMessage = ref(''), errorMessage = ref(''), previewImage = ref(null), showPreview = ref(false)
const selectedRound = computed(() => rounds.value.find((r) => r.round_key === selectedRoundId.value) || null)

function loadSavedRoundKeys() { try { const saved = JSON.parse(localStorage.getItem('meowverse:import-fee-saved-rounds') || '[]'); return new Set(Array.isArray(saved) ? saved.map(String) : []) } catch { return new Set() } }
function rememberSavedRound(key) { if (!key) return; const next = new Set(savedRoundKeys.value); next.add(String(key)); savedRoundKeys.value = next; localStorage.setItem('meowverse:import-fee-saved-rounds', JSON.stringify([...next])) }
const hasSavedImportFee = computed(() => Boolean(selectedRound.value?.has_saved_import_fee || (selectedRound.value?.round_key && savedRoundKeys.value.has(String(selectedRound.value.round_key)))))
function normalizeArrivalStatus(value) { const v = String(value || 'Pending').trim().toLowerCase(); return v === 'delayed' ? 'Delayed' : v === 'missing' ? 'Missing' : v === 'pending' ? 'Pending' : 'Arrived' }
function normalizePackSize(value) { const v = String(value ?? '').trim(); return v || '__unspecified__' }
function packLabel(value) { const v = String(value ?? '').trim(); return v && v !== '__unspecified__' ? `ขนาด ${v}` : 'ไม่ระบุขนาด' }
function groupKey(prodId, packSize, segment) { return `${prodId}|${normalizePackSize(packSize)}|Arrived|${segment || 'Main'}`.toLowerCase() }
function feeValue(group, fallback = 0) { const raw = feeInputs.value[group.key]; return raw === undefined || raw === '' ? Number(fallback) || 0 : Math.max(Number(raw) || 0, 0) }

const primaryProducts = computed(() => {
  if (!selectedRound.value?.products) return []
  const products = new Map()
  for (const raw of selectedRound.value.products) {
    const status = normalizeArrivalStatus(raw.arrival_status), packSize = normalizePackSize(raw.pack_size), segment = raw.fee_segment || selectedRound.value.fee_segment || 'Main', productKey = String(raw.prod_id)
    if (!products.has(productKey)) products.set(productKey, { key: productKey, prod_id: raw.prod_id, product_name: raw.product_name, image_url: raw.image_url || '', items: [], packs: new Map() })
    const product = products.get(productKey)
    const item = { ...raw, key: raw.key || `${productKey}|${raw.flavor || ''}|${packSize}|${status}|${segment}`, flavorDisplay: raw.flavor || '', ordered_qty: Number(raw.total_sold_qty) || 0, total_received_qty: Number(raw.total_received_qty) || 0, current_import_fee: Number(raw.current_import_fee) || 0, pack_size: packSize, arrival_status: status, canEnterImportFee: status === 'Arrived' && (Number(raw.total_received_qty) || 0) >= (Number(raw.total_sold_qty) || 0) }
    product.items.push(item)
    const key = groupKey(raw.prod_id, packSize, segment)
    if (!product.packs.has(key)) product.packs.set(key, { key, prod_id: raw.prod_id, pack_size: packSize, fee_segment: segment, items: [] })
    product.packs.get(key).items.push(item)
  }
  return [...products.values()].map((product) => {
    const packGroups = [...product.packs.values()].map((group) => { const eligibleItems = group.items.filter((item) => item.canEnterImportFee); const totalQty = eligibleItems.reduce((sum, item) => sum + item.ordered_qty, 0); const currentFee = eligibleItems.reduce((sum, item) => sum + item.current_import_fee, 0); const fee = feeValue(group, currentFee); const customerCount = Number(eligibleItems[0]?.customer_count) || 0; return { ...group, totalQty, currentFee, totalFee: fee, averageFee: totalQty > 0 ? fee / totalQty : 0, customerCount, canEnter: group.items.every((item) => item.canEnterImportFee), isFeeLocked: group.items.some((item) => !item.canEnterImportFee) } })
    const totalQty = packGroups.reduce((sum, group) => sum + group.totalQty, 0), totalFee = packGroups.reduce((sum, group) => sum + group.totalFee, 0)
    return { ...product, packGroups, totalQty, totalFee, averageFee: totalQty > 0 ? totalFee / totalQty : 0, hasMultiplePackSizes: packGroups.length > 1, variantCount: product.items.length, customerCount: Math.max(...product.items.map((item) => Number(item.customer_count) || 0), 0) }
  })
})
const hasUnspecifiedPackSize = computed(() => primaryProducts.value.some((product) => product.packGroups.some((group) => group.pack_size === '__unspecified__')))
const previewRows = computed(() => primaryProducts.value.flatMap((product) => product.packGroups.map((group) => ({ key: `${product.key}|${group.key}`, product_name: product.product_name, pack_size: group.pack_size, totalQty: group.totalQty, fee: feeValue(group, group.currentFee), averageFee: group.totalQty > 0 ? feeValue(group, group.currentFee) / group.totalQty : 0 }))))
const previewTotal = computed(() => previewRows.value.reduce((sum, row) => sum + row.fee, 0))
function isGroupInputLocked(group) { return !group || group.isFeeLocked || (hasSavedImportFee.value && !isEditMode.value) }
function isExpanded(key) { return expandedProductKeys.value.has(key) }
function toggleExpanded(key) { const next = new Set(expandedProductKeys.value); if (next.has(key)) next.delete(key); else next.add(key); expandedProductKeys.value = next }
function openImagePreview(url, title) { if (url) previewImage.value = { url, title } }
function closeImagePreview() { previewImage.value = null }
function authHeaders() { const user = currentUser.value || {}; return { 'Content-Type': 'application/json', 'x-user-role': String(user.role || '').toLowerCase() || 'admin', 'x-user-id': String(user.user_id || user.id || '') } }
function statusBadgeClass(value) { const v = String(value || '').toLowerCase(); return v === 'active' ? 'badge--active' : v === 'closed' ? 'badge--closed' : 'badge--default' }
function statusLabel(value) { const v = String(value || '').toLowerCase(); return v === 'active' ? 'เปิดอยู่' : v === 'closed' ? 'ปิดแล้ว' : value }
function formatMoney(value) { return new Intl.NumberFormat('th-TH', { style: 'currency', currency: 'THB', maximumFractionDigits: 2 }).format(Number(value) || 0) }
function normalizeFeeInput(value) { let v = String(value ?? '').replace(',', '.').replace(/[^\d.]/g, ''); const dot = v.indexOf('.'); if (dot >= 0) v = `${v.slice(0, dot) || '0'}.${v.slice(dot + 1).replace(/\./g, '').slice(0, 2)}`; return v }
function onFeeInput(key, event) { feeInputs.value[key] = normalizeFeeInput(event?.target?.value) }
function onFeeInputBlur(key) { if (!String(feeInputs.value[key] ?? '').trim() || feeInputs.value[key] === '.') feeInputs.value[key] = '0' }

async function fetchRounds() { loading.value = true; isEditMode.value = false; errorMessage.value = ''; try { const res = await fetch(`${API_BASE_URL}/admin/preorder-import-fee/rounds`, { headers: authHeaders() }); if (!res.ok) throw new Error(`โหลดรอบพรีออเดอร์ไม่สำเร็จ (${res.status})`); const data = await res.json(); rounds.value = data.filter((round) => String(round.fee_segment || 'Main').toLowerCase() === 'missing' || String(round.arrival_status || '').toLowerCase() === 'arrived'); if (!rounds.value.some((round) => round.round_key === selectedRoundId.value)) selectedRoundId.value = rounds.value[0]?.round_key || '' } catch (error) { errorMessage.value = translateError(error) } finally { loading.value = false } }
watch(selectedRoundId, () => { isEditMode.value = false; showPreview.value = false; feeInputs.value = {}; expandedProductKeys.value = new Set(); successMessage.value = ''; errorMessage.value = ''; for (const product of primaryProducts.value) for (const group of product.packGroups) feeInputs.value[group.key] = group.canEnter ? String(group.currentFee) : '' })
function requestEdit() { if (!hasSavedImportFee.value || isEditMode.value) return; if (!window.confirm('ยืนยันการแก้ไขค่านำเข้า? ระบบจะแสดงยอดก่อนบันทึกอีกครั้ง')) return; isEditMode.value = true; successMessage.value = ''; errorMessage.value = '' }
function buildFeePayload() { const fees = []; for (const product of primaryProducts.value) for (const group of product.packGroups) { const raw = feeInputs.value[group.key]; if (!isGroupInputLocked(group) && (raw === '' || raw == null || raw === '.' || !Number.isFinite(Number(raw)) || Number(raw) < 0)) throw new Error(`กรุณากรอกค่านำเข้าของ ${product.product_name} (${packLabel(group.pack_size)})`); fees.push({ prod_id: group.prod_id, pack_size: group.pack_size === '__unspecified__' ? null : group.pack_size, arrival_status: 'Arrived', fee_segment: group.fee_segment, import_fee: Math.round(feeValue(group, group.currentFee) * 100) / 100 }) } return fees }
function openSavePreview() { errorMessage.value = ''; try { buildFeePayload(); showPreview.value = true } catch (error) { errorMessage.value = error.message } }
async function saveImportFees() { if (!selectedRound.value || (hasSavedImportFee.value && !isEditMode.value)) return; try { const fees = buildFeePayload(); saving.value = true; showPreview.value = false; errorMessage.value = ''; successMessage.value = ''; const res = await fetch(`${API_BASE_URL}/admin/preorder-import-fee/${selectedRound.value.round_id}`, { method: 'PUT', headers: authHeaders(), body: JSON.stringify({ fees, segment: selectedRound.value.arrival_status, fee_segment: selectedRound.value.fee_segment || 'Main' }) }); const data = await res.json().catch(() => ({})); if (!res.ok || !data.success) throw new Error(data.message || `บันทึกค่านำเข้าไม่สำเร็จ (${res.status})`); successMessage.value = data.message || 'บันทึกค่านำเข้าเรียบร้อย'; rememberSavedRound(selectedRound.value.round_key); isEditMode.value = false; await fetchRounds() } catch (error) { errorMessage.value = translateError(error) } finally { saving.value = false } }
function onKeydown(event) { if (event.key === 'Escape') { showPreview.value = false; closeImagePreview() } }
onMounted(() => { fetchRounds(); window.addEventListener('meowverse:inventory-intake-updated', fetchRounds); window.addEventListener('keydown', onKeydown) })
onUnmounted(() => { window.removeEventListener('meowverse:inventory-intake-updated', fetchRounds); window.removeEventListener('keydown', onKeydown) })
</script>

